// BuyerServiceHandler is an implementation of the hawkr.buyer.BuyerService service.
type BuyerServiceHandler interface {
	// Profile
	GetBuyerProfile(context.Context, *connect.Request[buyer.GetBuyerProfileRequest]) (*connect.Response[buyer.BuyerProfileResponse], error)
	// PK（buyer_id）版本的 GetBuyerProfile——理由同 BatchGetBuyerMetaByBuyerIDs。
	GetBuyerProfileByBuyerID(context.Context, *connect.Request[buyer.GetBuyerProfileByBuyerIDRequest]) (*connect.Response[buyer.BuyerProfileResponse], error)
	GetBuyerProfileBatch(context.Context, *connect.Request[buyer.GetBuyerProfileBatchRequest]) (*connect.Response[buyer.GetBuyerProfileBatchResponse], error)
	UpdateBuyerProfile(context.Context, *connect.Request[buyer.UpdateBuyerProfileRequest]) (*connect.Response[buyer.BuyerProfileResponse], error)
	// EnsureBuyerProfile provisions/revives the buyer profile at role grant (login).
	// Idempotent: create if absent, revive-to-fresh if soft-deleted, no-op if active.
	EnsureBuyerProfile(context.Context, *connect.Request[buyer.EnsureBuyerProfileRequest]) (*connect.Response[buyer.BuyerProfileResponse], error)
	// Address
	GetAddressList(context.Context, *connect.Request[buyer.GetAddressListRequest]) (*connect.Response[buyer.AddressListResponse], error)
	GetAddress(context.Context, *connect.Request[buyer.GetAddressRequest]) (*connect.Response[buyer.GetAddressResponse], error)
	AddAddress(context.Context, *connect.Request[buyer.AddAddressRequest]) (*connect.Response[buyer.AddressOperationResponse], error)
	UpdateAddress(context.Context, *connect.Request[buyer.UpdateAddressRequest]) (*connect.Response[buyer.AddressOperationResponse], error)
	DeleteAddress(context.Context, *connect.Request[buyer.DeleteAddressRequest]) (*connect.Response[buyer.AddressOperationResponse], error)
	// 地址模糊搜尋 / 驗證（proxy 至 Google Maps，透過 pkg/geocode ACL）
	SuggestAddress(context.Context, *connect.Request[buyer.SuggestAddressRequest]) (*connect.Response[buyer.SuggestAddressResponse], error)
	ValidateAddress(context.Context, *connect.Request[buyer.ValidateAddressRequest]) (*connect.Response[buyer.ValidateAddressResponse], error)
	// Favorite (收藏)
	GetFavoriteList(context.Context, *connect.Request[buyer.GetFavoriteListRequest]) (*connect.Response[buyer.FavoriteListResponse], error)
	CheckFavorite(context.Context, *connect.Request[buyer.CheckFavoriteRequest]) (*connect.Response[buyer.CheckFavoriteResponse], error)
	BatchCheckFavorites(context.Context, *connect.Request[buyer.BatchCheckFavoritesRequest]) (*connect.Response[buyer.BatchCheckFavoritesResponse], error)
	AddFavorite(context.Context, *connect.Request[buyer.AddFavoriteRequest]) (*connect.Response[buyer.FavoriteOperationResponse], error)
	RemoveFavorite(context.Context, *connect.Request[buyer.RemoveFavoriteRequest]) (*connect.Response[buyer.FavoriteOperationResponse], error)
	GetFavoriteCount(context.Context, *connect.Request[buyer.GetFavoriteCountRequest]) (*connect.Response[buyer.FavoriteCountResponse], error)
	// 取得使用者所有收藏的 product_id 列表（供 product-service /public/products?followed_product_only=true 使用，見 02 §4.2.4）
	ListFavoritedProductIds(context.Context, *connect.Request[buyer.ListFavoritedProductIdsRequest]) (*connect.Response[buyer.ListFavoritedProductIdsResponse], error)
	// 取得使用者所有追蹤的 seller_id 列表（供 product-service /public/products?followed_seller_only=true 使用，見 02 §4.2.4）
	ListSubscribedSellerIds(context.Context, *connect.Request[buyer.ListSubscribedSellerIdsRequest]) (*connect.Response[buyer.ListSubscribedSellerIdsResponse], error)
	// Subscription (訂閱賣家)
	GetSubscriptionList(context.Context, *connect.Request[buyer.GetSubscriptionListRequest]) (*connect.Response[buyer.SubscriptionListResponse], error)
	SubscribeSeller(context.Context, *connect.Request[buyer.SubscribeSellerRequest]) (*connect.Response[buyer.SubscribeSellerResponse], error)
	UnsubscribeSeller(context.Context, *connect.Request[buyer.UnsubscribeSellerRequest]) (*connect.Response[buyer.UnsubscribeSellerResponse], error)
	CheckSubscription(context.Context, *connect.Request[buyer.CheckSubscriptionRequest]) (*connect.Response[buyer.CheckSubscriptionResponse], error)
	GetSubscribersList(context.Context, *connect.Request[buyer.GetSubscribersListRequest]) (*connect.Response[buyer.SubscribersListResponse], error)
	GetSubscriberDashboardStats(context.Context, *connect.Request[buyer.GetSubscriberDashboardStatsRequest]) (*connect.Response[buyer.SubscriberDashboardStatsResponse], error)
	// 批次取得多個賣家的訂閱數（內部服務間呼叫）
	BatchGetSubscriberCounts(context.Context, *connect.Request[buyer.BatchGetSubscriberCountsRequest]) (*connect.Response[buyer.BatchGetSubscriberCountsResponse], error)
	// Saved Items（收藏中心聚合讀 API，issue #2362 Phase 1：僅涵蓋 product/seller，貼文/食譜是 non-goal）
	GetSavedItems(context.Context, *connect.Request[buyer.GetSavedItemsRequest]) (*connect.Response[buyer.SavedItemsResponse], error)
	// Visit (瀏覽記錄)
	GetVisitList(context.Context, *connect.Request[buyer.GetVisitListRequest]) (*connect.Response[buyer.VisitListResponse], error)
	RecordVisit(context.Context, *connect.Request[buyer.RecordVisitRequest]) (*connect.Response[buyer.VisitOperationResponse], error)
	ClearVisitHistory(context.Context, *connect.Request[buyer.ClearVisitHistoryRequest]) (*connect.Response[buyer.VisitOperationResponse], error)
	// Avatar
	UpdateBuyerAvatar(context.Context, *connect.Request[buyer.UpdateBuyerAvatarRequest]) (*connect.Response[buyer.UpdateBuyerAvatarResponse], error)
	// ========== 會員卡 ==========
	// 查詢買家在各賣家的累計消費金額（會員卡清單）
	GetMemberCards(context.Context, *connect.Request[buyer.GetMemberCardsRequest]) (*connect.Response[buyer.GetMemberCardsResponse], error)
	// 查詢買家在特定賣家的消費紀錄明細
	GetSpendingRecords(context.Context, *connect.Request[buyer.GetSpendingRecordsRequest]) (*connect.Response[buyer.GetSpendingRecordsResponse], error)
	// ========== Cross-Service: Buyer Meta ==========
	// PK（buyer_id）版本的 BatchGetBuyerMeta。訂單/評論/訊息上持久化的欄位存的
	// 是 buyer_id（那個時間點的買家身分），不是 account_id——buyer_id 設計上
	// 永遠不等於 account_id（連第一個 stint 也一樣），把它塞進上面那支
	// account_id/current-stint 版本一律查無此人靜默回空。任何消費「持久化
	// buyer_id」的呼叫端都該走這支，即使該帳號已重新註冊產生新 stint 也能
	// 解析回當時那個 buyer_id 的資料（比照 seller 模組 GetSellerBatch 的
	// PK lookup 設計）。回應 map key 與 BuyerMeta.buyer_id 都承載 buyer_id。
	BatchGetBuyerMetaByBuyerIDs(context.Context, *connect.Request[buyer.BatchGetBuyerMetaByBuyerIDsRequest]) (*connect.Response[buyer.BatchGetBuyerMetaByBuyerIDsResponse], error)
	// ========== Cross-Role Guards: Principal Resolution ==========
	// 解析 buyer_id → 登入 principal account_id（② 買家 store-stint re-key
	// W2/W3，mirrors the seller module ResolvePrincipals；供 im-service
	// SendMessage 自我對話防護用）。只解析存活的買家；其餘的 id 不在 principals 裡，只出現在 unresolved_ids。
	ResolvePrincipals(context.Context, *connect.Request[buyer.ResolvePrincipalsRequest]) (*connect.Response[buyer.ResolvePrincipalsResponse], error)
	// ========== Restock Subscription (補貨通知訂閱，2026-06 新增 #942) ==========
	// 訂閱商品補貨通知（冪等：已有 ACTIVE 行回原 id）
	SubscribeRestock(context.Context, *connect.Request[buyer.SubscribeRestockRequest]) (*connect.Response[buyer.SubscribeRestockResponse], error)
	// 取消補貨訂閱（UPDATE ACTIVE→CANCELLED；無 ACTIVE 為 no-op）
	UnsubscribeRestock(context.Context, *connect.Request[buyer.UnsubscribeRestockRequest]) (*connect.Response[buyer.UnsubscribeRestockResponse], error)
	// 我的補貨訂閱清單（分頁 + product enrich）
	ListRestockSubscriptions(context.Context, *connect.Request[buyer.ListRestockSubscriptionsRequest]) (*connect.Response[buyer.ListRestockSubscriptionsResponse], error)
	// 批次檢查多個 product 是否訂閱（PDP detail / 訂閱列表頁 client-side cache）
	BatchCheckRestockSubscriptions(context.Context, *connect.Request[buyer.BatchCheckRestockSubscriptionsRequest]) (*connect.Response[buyer.BatchCheckRestockSubscriptionsResponse], error)
	// ========== Internal: PII-Purge Historical Stint Lookup (D8, buyer-store-stint-rekey-w2w3) ==========
	// Returns ALL buyer_id stints ever assigned to this account_id, including
	// closed ones — unlike GetBuyerProfile/EnsureBuyerProfile, which only ever
	// resolve the CURRENT stint. INTERNAL USE ONLY: exists solely for the
	// buyer.deleted/account.deleted PII-purge consumer (im-service) to
	// enumerate every buyer_id a message's sender_id may have used across
	// re-registrations, so it can scrub all of them. Do not call this from any
	// caller-facing feature, authorization check, or display path.
	ListBuyerIDsByAccount(context.Context, *connect.Request[buyer.ListBuyerIDsByAccountRequest]) (*connect.Response[buyer.ListBuyerIDsByAccountResponse], error)
	// ========== Display: Tombstone-safe Name Resolution (#2830) ==========
	// 解析 buyer_id → **可公開顯示**的名字，已註銷的 stint 也解得出來。
	//
	// 🔴 與 BatchGetBuyerMetaByBuyerIDs 的差別，以及為什麼需要兩支：
	// 那支帶 `deleted_at IS NULL`（`GetBuyersByBuyerIDs`），那是**刻意的 PII 邊界**
	// ——帳號關閉後不再供應個資，gateway 有測試把它的 404 行為釘成契約。但它的
	// 副作用是：所有持有歷史 buyer_id 的顯示面（評論作者、訂單買家、對話對象）
	// 在買家註銷後一律變成空字串，而各前端各自發明了不同的 fallback
	// （匿名買家／匿名／會員xxxx／顧客／-／買家／欄位直接消失，共七種）。
	//
	// 本 RPC 的解法是**在來源就給出可顯示的值**，而不是讓 N 個顯示端各補一次：
	//   - 未註銷 → 回真實 display_name
	//   - 已註銷 → **一律回墓碑字串**（與 SetBuyerPIICleared 寫進欄位的同一個常數），
	//     即使該 stint 的 PII 尚未被 30 天 cron 清掉，**真名也不會離開 DB**
	//   - avatar_key 對已註銷者恆為空（頭像是個資）
	//
	// ⇒ PII 邊界原封不動：已註銷 stint 沒有任何個資經由本 RPC 過線。
	// ⇒ 「map 有 key ＝ 解析成功／沒有 key ＋ error ＝ 服務不可用」結構上可區分，
	//    呼叫端不再需要靠空字串去猜是哪一種。
	BatchGetBuyerDisplayByBuyerIDs(context.Context, *connect.Request[buyer.BatchGetBuyerDisplayByBuyerIDsRequest]) (*connect.Response[buyer.BatchGetBuyerDisplayByBuyerIDsResponse], error)
	// ========== Admin: Buyer Statistics ==========
	GetBuyerStatsForAdmin(context.Context, *connect.Request[buyer.GetBuyerStatsForAdminRequest]) (*connect.Response[buyer.GetBuyerStatsForAdminResponse], error)
	GetBuyerEntitlement(context.Context, *connect.Request[buyer.GetBuyerEntitlementRequest]) (*connect.Response[buyer.BuyerEntitlement], error)
	AssignMembership(context.Context, *connect.Request[buyer.AssignMembershipRequest]) (*connect.Response[buyer.BuyerEntitlement], error)
	// Admin: membership_plans 目錄本身的讀寫（doc 59 §6.1 從未定義過的缺口，
	// 2026-08-28 ADR「子系統 2-4 排序」D1 拉出來獨立先做）。
	ListMembershipPlans(context.Context, *connect.Request[buyer.ListMembershipPlansRequest]) (*connect.Response[buyer.ListMembershipPlansResponse], error)
	UpdateMembershipPlan(context.Context, *connect.Request[buyer.UpdateMembershipPlanRequest]) (*connect.Response[buyer.UpdateMembershipPlanResponse], error)
}

